/**
 * Every error, by the hundreds digit of its stable `code`.
 *
 * `code` is `leek_zcash::LeekError::code` (the README lists them),
 * `recovery` its `Recovery`, `reason` a fixed sentence per code that never
 * carries an amount, an address, a key or PCZT bytes, so it can go to logs.
 * `device_code` is the firmware's code when the board refused with one this
 * version does not know (`code` 900).
 */
sealed class LeekException: kotlin.Exception() {
    
    /**
     * 1xx: the link (not found, permission, dropped, timeout, cancelled).
     */
    class Link(
        
        val `code`: kotlin.UShort, 
        
        val `recovery`: Recovery, 
        
        val `reason`: kotlin.String
        ) : LeekException() {
        override val message
            get() = "code=${ `code` }, recovery=${ `recovery` }, reason=${ `reason` }"
    }
    
    /**
     * 2xx: the session and the board's state (pairing, locked, busy, ...).
     */
    class Session(
        
        val `code`: kotlin.UShort, 
        
        val `recovery`: Recovery, 
        
        val `reason`: kotlin.String
        ) : LeekException() {
        override val message
            get() = "code=${ `code` }, recovery=${ `recovery` }, reason=${ `reason` }"
    }
    
    /**
     * 3xx: the user said no, or did not answer, on the board.
     */
    class User(
        
        val `code`: kotlin.UShort, 
        
        val `recovery`: Recovery, 
        
        val `reason`: kotlin.String
        ) : LeekException() {
        override val message
            get() = "code=${ `code` }, recovery=${ `recovery` }, reason=${ `reason` }"
    }
    
    /**
     * 4xx: account and network.
     */
    class Account(
        
        val `code`: kotlin.UShort, 
        
        val `recovery`: Recovery, 
        
        val `reason`: kotlin.String
        ) : LeekException() {
        override val message
            get() = "code=${ `code` }, recovery=${ `recovery` }, reason=${ `reason` }"
    }
    
    /**
     * 5xx: the PCZT (unsupported, too large, does not parse, ...).
     */
    class Pczt(
        
        val `code`: kotlin.UShort, 
        
        val `recovery`: Recovery, 
        
        val `reason`: kotlin.String
        ) : LeekException() {
        override val message
            get() = "code=${ `code` }, recovery=${ `recovery` }, reason=${ `reason` }"
    }
    
    /**
     * 6xx: the signatures (`.zsig` for other bytes, a bad signature, ...).
     */
    class Signature(
        
        val `code`: kotlin.UShort, 
        
        val `recovery`: Recovery, 
        
        val `reason`: kotlin.String
        ) : LeekException() {
        override val message
            get() = "code=${ `code` }, recovery=${ `recovery` }, reason=${ `reason` }"
    }
    
    /**
     * 7xx: stored app data (an invalid app identifier, data sealed for
     * another key, damaged data, a forgotten Storage Key).
     */
    class Storage(
        
        val `code`: kotlin.UShort, 
        
        val `recovery`: Recovery, 
        
        val `reason`: kotlin.String
        ) : LeekException() {
        override val message
            get() = "code=${ `code` }, recovery=${ `recovery` }, reason=${ `reason` }"
    }
    
    /**
     * 9xx: a firmware error code this version does not know.
     */
    class Device(
        
        val `code`: kotlin.UShort, 
        
        val `recovery`: Recovery, 
        
        val `reason`: kotlin.String, 
        
        val `deviceCode`: kotlin.UShort
        ) : LeekException() {
        override val message
            get() = "code=${ `code` }, recovery=${ `recovery` }, reason=${ `reason` }, deviceCode=${ `deviceCode` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LeekException> {
        override fun lift(error_buf: RustBuffer.ByValue): LeekException = FfiConverterTypeLeekError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLeekError : FfiConverterRustBuffer<LeekException> {
    override fun read(buf: ByteBuffer): LeekException {
        

        return when(buf.getInt()) {
            1 -> LeekException.Link(
                FfiConverterUShort.read(buf),
                FfiConverterTypeRecovery.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> LeekException.Session(
                FfiConverterUShort.read(buf),
                FfiConverterTypeRecovery.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> LeekException.User(
                FfiConverterUShort.read(buf),
                FfiConverterTypeRecovery.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> LeekException.Account(
                FfiConverterUShort.read(buf),
                FfiConverterTypeRecovery.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> LeekException.Pczt(
                FfiConverterUShort.read(buf),
                FfiConverterTypeRecovery.read(buf),
                FfiConverterString.read(buf),
                )
            6 -> LeekException.Signature(
                FfiConverterUShort.read(buf),
                FfiConverterTypeRecovery.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> LeekException.Storage(
                FfiConverterUShort.read(buf),
                FfiConverterTypeRecovery.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> LeekException.Device(
                FfiConverterUShort.read(buf),
                FfiConverterTypeRecovery.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUShort.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LeekException): ULong {
        return when(value) {
            is LeekException.Link -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterTypeRecovery.allocationSize(value.`recovery`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LeekException.Session -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterTypeRecovery.allocationSize(value.`recovery`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LeekException.User -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterTypeRecovery.allocationSize(value.`recovery`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LeekException.Account -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterTypeRecovery.allocationSize(value.`recovery`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LeekException.Pczt -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterTypeRecovery.allocationSize(value.`recovery`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LeekException.Signature -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterTypeRecovery.allocationSize(value.`recovery`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LeekException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterTypeRecovery.allocationSize(value.`recovery`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LeekException.Device -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterTypeRecovery.allocationSize(value.`recovery`)
                + FfiConverterString.allocationSize(value.`reason`)
                + FfiConverterUShort.allocationSize(value.`deviceCode`)
            )
        }
    }

    override fun write(value: LeekException, buf: ByteBuffer) {
        when(value) {
            is LeekException.Link -> {
                buf.putInt(1)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterTypeRecovery.write(value.`recovery`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LeekException.Session -> {
                buf.putInt(2)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterTypeRecovery.write(value.`recovery`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LeekException.User -> {
                buf.putInt(3)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterTypeRecovery.write(value.`recovery`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LeekException.Account -> {
                buf.putInt(4)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterTypeRecovery.write(value.`recovery`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LeekException.Pczt -> {
                buf.putInt(5)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterTypeRecovery.write(value.`recovery`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LeekException.Signature -> {
                buf.putInt(6)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterTypeRecovery.write(value.`recovery`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LeekException.Storage -> {
                buf.putInt(7)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterTypeRecovery.write(value.`recovery`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LeekException.Device -> {
                buf.putInt(8)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterTypeRecovery.write(value.`recovery`, buf)
                FfiConverterString.write(value.`reason`, buf)
                FfiConverterUShort.write(value.`deviceCode`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * How the bytes over a [`FrameTransport`] are delimited.
 */

enum class LinkKind {
    
    /**
     * A byte stream (USB CDC): `send` writes raw bytes, `recv` returns
     * whatever arrived; framing ("LK" sync, length, CRC) is done here.
     * Like the Android app's `UsbIo`.
     */
    STREAM,
    /**
     * Whole frames (Bluetooth LE, where GATT delimits them): each `send`
     * and each `recv` is one frame, a big-endian u16 length (type byte
     * included), the type, the payload. Like `BleIo`.
     */
    FRAMES;
    companion object
}


