/**
 * Where `sign_pczt` is.
 */
sealed class SignProgress {
    
    object Checking : SignProgress()
    
    
    data class Uploading(
        val `sent`: kotlin.ULong, 
        val `total`: kotlin.ULong) : SignProgress() {
        companion object
    }
    
    /**
     * The user reviews the transaction on the board.
     */
    object ReviewOnDevice : SignProgress()
    
    
    object Applying : SignProgress()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSignProgress : FfiConverterRustBuffer<SignProgress>{
    override fun read(buf: ByteBuffer): SignProgress {
        return when(buf.getInt()) {
            1 -> SignProgress.Checking
            2 -> SignProgress.Uploading(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            3 -> SignProgress.ReviewOnDevice
            4 -> SignProgress.Applying
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SignProgress) = when(value) {
        is SignProgress.Checking -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is SignProgress.Uploading -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`sent`)
                + FfiConverterULong.allocationSize(value.`total`)
            )
        }
        is SignProgress.ReviewOnDevice -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is SignProgress.Applying -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: SignProgress, buf: ByteBuffer) {
        when(value) {
            is SignProgress.Checking -> {
                buf.putInt(1)
                Unit
            }
            is SignProgress.Uploading -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`sent`, buf)
                FfiConverterULong.write(value.`total`, buf)
                Unit
            }
            is SignProgress.ReviewOnDevice -> {
                buf.putInt(3)
                Unit
            }
            is SignProgress.Applying -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





