/**
 * Why the host's transport failed.
 */
sealed class TransportFailure: kotlin.Exception() {
    
    /**
     * No board on this link (unplugged, out of range).
     */
    class NotFound(
        ) : TransportFailure() {
        override val message
            get() = ""
    }
    
    /**
     * The platform refused access (USB permission, Bluetooth permission).
     */
    class PermissionDenied(
        ) : TransportFailure() {
        override val message
            get() = ""
    }
    
    /**
     * The link dropped.
     */
    class Disconnected(
        ) : TransportFailure() {
        override val message
            get() = ""
    }
    
    /**
     * The host's callback threw something else.
     */
    class Unexpected(
        ) : TransportFailure() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TransportFailure> {
        override fun lift(error_buf: RustBuffer.ByValue): TransportFailure = FfiConverterTypeTransportFailure.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeTransportFailure : FfiConverterRustBuffer<TransportFailure> {
    override fun read(buf: ByteBuffer): TransportFailure {
        

        return when(buf.getInt()) {
            1 -> TransportFailure.NotFound()
            2 -> TransportFailure.PermissionDenied()
            3 -> TransportFailure.Disconnected()
            4 -> TransportFailure.Unexpected()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TransportFailure): ULong {
        return when(value) {
            is TransportFailure.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is TransportFailure.PermissionDenied -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is TransportFailure.Disconnected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is TransportFailure.Unexpected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: TransportFailure, buf: ByteBuffer) {
        when(value) {
            is TransportFailure.NotFound -> {
                buf.putInt(1)
                Unit
            }
            is TransportFailure.PermissionDenied -> {
                buf.putInt(2)
                Unit
            }
            is TransportFailure.Disconnected -> {
                buf.putInt(3)
                Unit
            }
            is TransportFailure.Unexpected -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




